        let before = Settings::default();
        let after = Settings {
            forge: Forge::Github,
            ..Settings::default()
        };
        assert_eq!(after.changes(&before), ["forge: local -> github"]);
        assert_eq!(after.model(Stage::Build), &Model::default());
    }
