        &at(Stage::Deploy, State::Running),
        &failed("health check red"),
    );
    assert_eq!((j.stage, j.state), (Stage::Deploy, State::NeedsYou));
}

#[test]
fn comments_at_the_picks_and_uat_send_the_work_to_implement() {
